INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 40, 'theory', 'Quiz: Files, Processes, and Sockets');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 40, 0, 'Why must a buffered writer (BufWriter) be flushed or dropped?', '["To release the file name", "Otherwise the last data accumulated in the buffer may never reach the file", "To change the encoding", "This is only needed for sockets"]', 1, 'A buffer accumulates writes and sends them less often, to cut the number of system calls.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 40, 1, 'What is the right way to match on a file-open error?', '["By the message text", "By e.kind(): ErrorKind::NotFound, PermissionDenied, and so on", "Through unwrap", "By the process exit code"]', 1, 'The error kind does not depend on the message language or the platform.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 40, 2, 'Why are Command arguments passed as a list rather than as one string?', '["It is faster", "There is no shell parsing: an extra command cannot be injected with a space or a quote", "Windows requires it", "To save memory"]', 1, 'Command does not start a shell: arguments reach the program exactly as passed.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 40, 3, 'Why is it important to close the stdin of a child process after writing to it?', '["It frees memory", "The program (for example, sort) learns that no more data is coming, otherwise it waits forever", "Otherwise the output will be in a different encoding", "It is optional"]', 1, 'Closing the pipe is end of file for the reading side.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 40, 4, 'What does port 0 mean in bind?', '["A forbidden port", "The system picks any free port; you can find the number via local_addr()", "The default port 80", "The broadcast address"]', 1, 'Handy for tests and examples: there is no need to agree on a port number in advance.');
